corporate_design.toad_component_blueprint:
canvas {
  size: 920px 580px;
  fill: #E0F2FE;
  font-family: "Inter, sans-serif";
}

>glassAqua = #0284C7;
>frameDark = #0F172A;

rect #glassPanel {
  at: center of canvas;
  size: 820px 480px;
  fill: #FFFFFF;
  stroke: >glassAqua;
  stroke-width: 1px;
  radius: 12px;
}

text #glassTitle {
  at: top left of #glassPanel offset 36px 36px;
  content: "GLASWERK OBERLAND // STRUCTURAL FACADES";
  font-size: 13px;
  font-weight: 600;
  color: >glassAqua;
}

text #glassMain {
  at: below #glassTitle offset 14px;
  content: "Transparenz ohne Kompromisse bei Wärmeschutz";
  font-size: 30px;
  font-weight: 500;
  color: >frameDark;
}
